CREATE TABLE IF NOT EXISTS migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'dyna_app') THEN CREATE ROLE dyna_app NOLOGIN NOSUPERUSER NOBYPASSRLS; END IF; END $$;
CREATE TABLE tenants (id uuid PRIMARY KEY, name text NOT NULL, plan text NOT NULL DEFAULT 'business', currency text NOT NULL DEFAULT 'PLN', locale text NOT NULL DEFAULT 'pl-PL', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL);
CREATE TABLE memberships (user_id uuid REFERENCES users, tenant_id uuid REFERENCES tenants, role text CHECK(role IN ('admin','operator','viewer')), PRIMARY KEY(user_id,tenant_id));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid REFERENCES users, tenant_id uuid REFERENCES tenants, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE warehouses (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, name text NOT NULL, code text NOT NULL, UNIQUE(tenant_id,id), UNIQUE(tenant_id,code));
CREATE TABLE products (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, sku text NOT NULL, name text NOT NULL, ean text, price integer NOT NULL CHECK(price>=0), vat integer NOT NULL DEFAULT 23 CHECK(vat IN (0,5,8,23)), category text NOT NULL DEFAULT 'Pozostałe', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,sku), UNIQUE(tenant_id,id));
CREATE INDEX products_tenant_name ON products(tenant_id,name,id);
CREATE TABLE stock (tenant_id uuid NOT NULL, warehouse_id uuid NOT NULL, product_id uuid NOT NULL, on_hand integer NOT NULL DEFAULT 0 CHECK(on_hand>=0), reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=on_hand), available integer GENERATED ALWAYS AS (on_hand-reserved) STORED, location text NOT NULL DEFAULT 'A-01', PRIMARY KEY(tenant_id,warehouse_id,product_id), FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id), FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id));
CREATE TABLE orders (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, number text NOT NULL, source text NOT NULL DEFAULT 'manual', external_id text, channel_id uuid, customer_name text NOT NULL, email text NOT NULL, address jsonb NOT NULL DEFAULT '{}', currency text NOT NULL DEFAULT 'PLN', status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','paid','picking','packed','shipped','delivered','completed','cancelled','return_initiated','return_received','return_completed')), total integer NOT NULL CHECK(total>=0), shipping_cost integer NOT NULL DEFAULT 0 CHECK(shipping_cost>=0), warehouse_id uuid NOT NULL, note text NOT NULL DEFAULT '', portal_token text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,number), UNIQUE(tenant_id,channel_id,external_id), FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id));
CREATE INDEX orders_tenant_status_date ON orders(tenant_id,status,created_at DESC,id DESC);
CREATE INDEX orders_tenant_date ON orders(tenant_id,created_at DESC,id DESC);
CREATE TABLE order_items (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, order_id uuid NOT NULL, product_id uuid NOT NULL, name text NOT NULL, sku text NOT NULL, quantity integer NOT NULL CHECK(quantity>0), scanned integer NOT NULL DEFAULT 0 CHECK(scanned>=0 AND scanned<=quantity), price integer NOT NULL CHECK(price>=0), vat integer NOT NULL, UNIQUE(tenant_id,order_id,product_id), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id), FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id));
CREATE TABLE reservations (tenant_id uuid NOT NULL, order_id uuid NOT NULL, product_id uuid NOT NULL, warehouse_id uuid NOT NULL, quantity integer NOT NULL CHECK(quantity>0), state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','released','consumed')), PRIMARY KEY(tenant_id,order_id,product_id), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id), FOREIGN KEY(tenant_id,warehouse_id,product_id) REFERENCES stock(tenant_id,warehouse_id,product_id));
CREATE TABLE stock_movements (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, product_id uuid NOT NULL, warehouse_id uuid NOT NULL, order_id uuid, delta integer NOT NULL, kind text NOT NULL, note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,warehouse_id,product_id) REFERENCES stock(tenant_id,warehouse_id,product_id), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id));
CREATE INDEX movements_product_date ON stock_movements(tenant_id,product_id,created_at DESC);
CREATE TABLE order_events (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, order_id uuid NOT NULL, kind text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id));
CREATE INDEX events_order ON order_events(tenant_id,order_id,created_at);
CREATE TABLE shipments (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, order_id uuid NOT NULL, carrier text NOT NULL, tracking_number text NOT NULL, mode text NOT NULL CHECK(mode IN ('demo','sandbox','live')), status text NOT NULL DEFAULT 'created', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,order_id), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id));
CREATE TABLE documents (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, order_id uuid NOT NULL, number text NOT NULL, kind text NOT NULL CHECK(kind IN ('invoice','correction')), mode text NOT NULL DEFAULT 'demo', data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,order_id,kind), UNIQUE(tenant_id,number), FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id));
CREATE TABLE audit_events (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, user_id uuid, action text NOT NULL, entity_id uuid, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_tenant_date ON audit_events(tenant_id,created_at DESC);
CREATE TABLE automation_rules (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, name text NOT NULL, trigger text NOT NULL, action text NOT NULL CHECK(action IN ('add_note')), config jsonb NOT NULL DEFAULT '{}', enabled boolean NOT NULL DEFAULT true);
CREATE TABLE jobs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, kind text NOT NULL, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','running','done','failed')), attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 5, run_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, error text, created_at timestamptz NOT NULL DEFAULT now(), dedup_key text NOT NULL, UNIQUE(tenant_id,dedup_key));
CREATE INDEX jobs_claim ON jobs(run_at,created_at) WHERE state='pending';
CREATE TABLE channels (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants, provider text NOT NULL, name text NOT NULL, mode text NOT NULL CHECK(mode IN ('sandbox','live')), credentials text NOT NULL, settings jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'not_verified', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
ALTER TABLE orders ADD FOREIGN KEY(tenant_id,channel_id) REFERENCES channels(tenant_id,id);
CREATE TABLE integration_runs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, channel_id uuid NOT NULL, operation text NOT NULL, status text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,channel_id) REFERENCES channels(tenant_id,id));
CREATE TABLE listings (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, channel_id uuid NOT NULL, product_id uuid NOT NULL, external_id text, status text NOT NULL DEFAULT 'draft', price integer NOT NULL CHECK(price>=0), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,channel_id) REFERENCES channels(tenant_id,id), FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id), UNIQUE(tenant_id,channel_id,product_id));
CREATE TABLE idempotency_keys (tenant_id uuid NOT NULL REFERENCES tenants, key text NOT NULL, request_hash text NOT NULL, response jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,key));
DO $$ DECLARE tbl text; BEGIN FOREACH tbl IN ARRAY ARRAY['tenants','warehouses','products','stock','orders','order_items','reservations','stock_movements','order_events','shipments','documents','audit_events','automation_rules','jobs','channels','integration_runs','listings','idempotency_keys'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tbl);
EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tbl);
EXECUTE format('CREATE POLICY tenant_scope ON %I TO dyna_app USING (%I = nullif(current_setting(''app.tenant_id'', true), '''')::uuid) WITH CHECK (%I = nullif(current_setting(''app.tenant_id'', true), '''')::uuid)',tbl,CASE WHEN tbl='tenants' THEN 'id' ELSE 'tenant_id' END,CASE WHEN tbl='tenants' THEN 'id' ELSE 'tenant_id' END);
EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON %I TO dyna_app',tbl);
END LOOP; END $$;
